const LOGO_DATA="data:image/jpeg;base64,";const KEY="impacto_pro_v3";
let db=JSON.parse(localStorage.getItem(KEY)||'{"products":[],"rentals":[],"quotes":[],"clients":[],"optionals":[]}');
if(!Array.isArray(db.products))db.products=[];
if(!Array.isArray(db.rentals))db.rentals=[];
if(!Array.isArray(db.quotes))db.quotes=[];
if(!Array.isArray(db.clients))db.clients=[];
if(!Array.isArray(db.optionals))db.optionals=[];

const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],money=v=>Number(v||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"}),esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));
function save(){localStorage.setItem(KEY,JSON.stringify(db));updateStorageState()}
function login(){if($("#u").value==="admin"&&$("#pw").value==="1234"){$("#login").classList.add("hidden");$("#app").classList.remove("hidden");page("dash");updateNetworkStatus()}else alert("Usuário ou senha inválidos.")}
function updateNetworkStatus(){const online=navigator.onLine;const n=$("#net");if(n){n.textContent=online?"● Online":"● Offline";n.className=online?"net-online":"net-offline"}const b=$("#mode-badge");if(b)b.textContent=online?"Conectado à internet":"Modo offline — dados salvos neste aparelho"}
window.addEventListener("online",updateNetworkStatus);window.addEventListener("offline",updateNetworkStatus);
function updateStorageState(){const s=$("#storage-state");if(s)s.textContent="Dados salvos automaticamente neste aparelho"}
function page(p){const t={dash:"Dashboard",quotes:"Orçamentos",optionals:"Opcionais",stock:"Estoque",rent:"Equipamentos alugados",history:"Histórico"};if(!t[p])p="dash";$("#title").textContent=t[p];$$("aside nav button").forEach(b=>b.classList.toggle("active",b.dataset.page===p));({dash,quotes,optionals,stock,rent,history}[p])()}
function dash(){$("#content").innerHTML=`<div class="hero-panel"><div><span class="eyebrow">GESTÃO PROFISSIONAL</span><h2>Impacto Pro Orçamentos</h2><p class="muted">Crie, edite e gere seus orçamentos mesmo sem internet.</p></div><div class="connection-card"><span id="mode-badge"></span><small id="storage-state">Dados salvos automaticamente neste aparelho</small></div></div><div class="cards"><div class="card"><span class="card-label">ORÇAMENTOS</span><b>${db.quotes.length}</b></div><div class="card"><span class="card-label">ITENS EM ESTOQUE</span><b>${db.products.reduce((a,p)=>a+Number(p.qty||0),0)}</b></div><div class="card"><span class="card-label">ALUGADOS</span><b>${db.products.filter(x=>(x.status||"Disponível")==="Alugado").length}</b></div><div class="card"><span class="card-label">OPCIONAIS</span><b>${db.optionals.length}</b></div></div><div class="panel welcome"><h3>Comece por um orçamento</h3><p class="muted">Os dados ficam disponíveis offline e são mantidos no armazenamento local do aparelho. Quando a internet voltar, o indicador muda automaticamente para <b>Online</b>.</p><button onclick="quoteModal()">+ Novo orçamento</button></div>`;updateNetworkStatus();updateStorageState()}
function optionals(){let rows=db.optionals.map(o=>`<tr><td><b>${esc(o.name)}</b></td><td>${esc(o.description||"—")}</td><td>${money(o.value)}</td><td><button class="ghost small" onclick="optionalModal(${o.id})">Editar</button> <button class="danger small" onclick="delOptional(${o.id})">Excluir</button></td></tr>`).join("");$("#content").innerHTML=`<div class="bar"><div><h2>Opcionais</h2><span class="muted">Itens extras que podem ser adicionados ao orçamento.</span></div><button onclick="optionalModal()">+ Novo opcional</button></div><div class="tablebox"><table class="table"><tr><th>Opcional</th><th>Descrição</th><th>Valor padrão</th><th>Ações</th></tr>${rows||'<tr><td colspan="4" class="empty">Nenhum opcional cadastrado.</td></tr>'}</table></div>`}
function optionalModal(id){let o=db.optionals.find(x=>x.id===id)||{name:"",description:"",value:0};modal(`<h3>${id?"Editar opcional":"Novo opcional"}</h3><div class="grid"><div class="field"><label>Nome</label><input id="on" value="${esc(o.name)}"></div><div class="field"><label>Valor padrão</label><input id="ovv" type="number" step=".01" value="${o.value}"></div><div class="field full"><label>Descrição</label><textarea id="od">${esc(o.description||"")}</textarea></div></div><br><button onclick="saveOptional(${id||0})">Salvar</button> <button class="ghost" onclick="closeModal()">Cancelar</button>`)}
function saveOptional(id){let o={id:id||Date.now(),name:$("#on").value.trim(),description:$("#od").value,value:Number($("#ovv").value||0)};if(!o.name)return alert("Informe o nome do opcional.");if(id)db.optionals=db.optionals.map(x=>x.id===id?o:x);else db.optionals.push(o);save();closeModal();optionals()}
function delOptional(id){if(confirm("Excluir este opcional?")){db.optionals=db.optionals.filter(x=>x.id!==id);save();optionals()}}
function stock(){let rows=db.products.map(p=>`<tr><td><b>${esc(p.name)}</b><br><span class="muted">${esc(p.category||"")}</span></td><td>${p.qty}</td><td>${money(p.value)}</td><td><span class="status ${statusClass(p.status||"Disponível")}">${esc(p.status||"Disponível")}</span></td><td><button class="ghost small" onclick="prodModal(${p.id})">Editar</button> <button class="danger small" onclick="delProd(${p.id})">Excluir</button></td></tr>`).join("");$("#content").innerHTML=`<div class="bar"><div><h2>Estoque</h2><span class="muted">Materiais e equipamentos.</span></div><button onclick="prodModal()">+ Novo item</button></div><div class="tablebox"><table class="table"><tr><th>Item</th><th>Qtd.</th><th>Valor</th><th>Status</th><th>Ações</th></tr>${rows||'<tr><td colspan="5" class="empty">Nenhum item.</td></tr>'}</table></div>`}
function prodModal(id){let p=db.products.find(x=>x.id===id)||{name:"",category:"",qty:0,value:0,status:"Disponível"};modal(`<h3>${id?"Editar item":"Novo item"}</h3><div class="grid"><div class="field"><label>Nome</label><input id="pn" value="${esc(p.name)}"></div><div class="field"><label>Categoria</label><input id="pc" value="${esc(p.category)}"></div><div class="field"><label>Quantidade</label><input id="pq" type="number" min="0" value="${p.qty}"></div><div class="field"><label>Valor padrão</label><input id="pv" type="number" step=".01" value="${p.value}"></div><div class="field"><label>Status</label><select id="ps"><option ${p.status==="Disponível"?"selected":""}>Disponível</option><option ${p.status==="Alugado"?"selected":""}>Alugado</option><option ${p.status==="Manutenção"?"selected":""}>Manutenção</option></select></div></div><br><button onclick="saveProd(${id||0})">Salvar</button> <button class="ghost" onclick="closeModal()">Cancelar</button>`)}
function saveProd(id){let p={id:id||Date.now(),name:$("#pn").value.trim(),category:$("#pc").value,qty:Number($("#pq").value||0),value:Number($("#pv").value||0),status:$("#ps").value};if(!p.name)return alert("Informe o nome.");if(id)db.products=db.products.map(x=>x.id===id?p:x);else db.products.push(p);save();closeModal();stock()}
function delProd(id){if(confirm("Excluir item?")){db.products=db.products.filter(x=>x.id!==id);save();stock()}}
function quotes(){let rows=db.quotes.map(q=>`<tr><td>${esc(q.number)}</td><td><b>${esc(q.clientName||"—")}</b><br><span class="muted">${esc(q.eventName||"")}</span></td><td>${esc(q.eventDate||q.date||"—")}</td><td><b>${money(q.total)}</b></td><td><div class="actions"><button class="ghost small" onclick="quoteModal(${q.id})">Editar</button><button class="small" onclick="pdf(${q.id})">PDF</button><button class="danger small" onclick="delQuote(${q.id})">Excluir</button></div></td></tr>`).join("");$("#content").innerHTML=`<div class="bar"><div><h2>Orçamentos</h2><span class="muted">Crie e edite propostas sem precisar cadastrar clientes.</span></div><button onclick="quoteModal()">+ Novo orçamento</button></div><div class="tablebox"><table class="table"><tr><th>Nº</th><th>Cliente</th><th>Evento / Data</th><th>Valor final</th><th>Ações</th></tr>${rows||'<tr><td colspan="5" class="empty">Nenhum orçamento.</td></tr>'}</table></div>`}
function quoteModal(id){
 let old=id&&db.quotes.find(q=>q.id===id),map={};(old?.items||[]).forEach(i=>map[i.productId]=i);let om={};(old?.optionals||[]).forEach(i=>om[i.id]=i);
 let lines=db.products.map(p=>{let x=map[p.id];return `<div class="qline"><input type="checkbox" data-p="${p.id}" ${x?"checked":""}><span>${esc(p.name)}</span><input class="qq" type="number" min="1" value="${x?.qty||1}"><input class="qv" type="number" step=".01" value="${x?.value??p.value}"><button class="ghost" onclick="this.parentNode.querySelector('[data-p]').checked=false;calc()">×</button></div>`}).join("");
 let ol=db.optionals.map(o=>{let x=om[o.id];return `<div class="qline"><input type="checkbox" data-o="${o.id}" ${x?"checked":""}><span>⭐ ${esc(o.name)}</span><input class="oq" type="number" min="1" value="${x?.qty||1}"><input class="ov" type="number" step=".01" value="${x?.value??o.value}"><button class="ghost" onclick="this.parentNode.querySelector('[data-o]').checked=false;calc()">×</button></div>`}).join("");
 if(!lines&&!ol)return alert("Cadastre equipamentos ou opcionais primeiro.");
 modal(`<h3>${id?"Editar orçamento":"Novo orçamento"}</h3><div class="grid"><div class="field full"><label>Cliente / Contratante</label><input id="qclient" value="${esc(old?.clientName||"")}" placeholder="Digite o nome do cliente"></div><div class="field full"><label>Evento</label><input id="qeventname" value="${esc(old?.eventName||"")}" placeholder="Ex.: 15 anos, casamento, formatura"></div><div class="field"><label>Data do evento</label><input id="qevent" type="date" value="${old?.eventDate||""}"></div><div class="field"><label>Horário do evento</label><input id="qtime" type="time" value="${old?.eventTime||""}"></div><div class="field"><label>Cerimonialista</label><input id="qcer" value="${esc(old?.cerimonialista||"")}"></div><div class="field"><label>Local do evento</label><input id="qlocal" value="${esc(old?.eventLocal||"")}" placeholder="Nome do local"></div><div class="field"><label>Cidade</label><input id="qcity" value="${esc(old?.eventCity||"")}" placeholder="Cidade / UF"></div></div><p class="section-title">Equipamentos</p><div class="qitems">${lines||'<div class="empty">Nenhum equipamento.</div>'}</div><p class="section-title">Opcionais</p><div class="qitems">${ol||'<div class="empty">Nenhum opcional.</div>'}</div><div class="finalbox"><label>VALOR FINAL — EDITÁVEL</label><input id="qt" type="number" step=".01" value="${old?.total??0}"></div><div class="field" style="margin-top:10px"><label>Observações</label><textarea id="qo">${esc(old?.notes||"")}</textarea></div><br><button onclick="saveQuote(${id||0})">${id?"Salvar alterações e gerar PDF":"Salvar e gerar PDF"}</button> <button class="ghost" onclick="closeModal()">Cancelar</button>`);
 $$(".qq,.qv,.oq,.ov,[data-p],[data-o]").forEach(x=>x.oninput=calc);if(!old)calc();
}
function calc(){let t=0;$$('.qline').forEach(l=>{let p=l.querySelector('[data-p]'),o=l.querySelector('[data-o]');if(p&&p.checked)t+=Number(l.querySelector('.qq').value||0)*Number(l.querySelector('.qv').value||0);if(o&&o.checked)t+=Number(l.querySelector('.oq').value||0)*Number(l.querySelector('.ov').value||0)});if(document.activeElement!==$('#qt')&&$('#qt'))$('#qt').value=t.toFixed(2)}
function saveQuote(id){
 let clientName=$("#qclient").value.trim();if(!clientName)return alert("Informe o nome do cliente/contratante.");let items=[],optionals=[];
 $$(".qline").forEach(l=>{let p=l.querySelector("[data-p]"),o=l.querySelector("[data-o]");if(p&&p.checked)items.push({productId:Number(p.dataset.p),name:l.children[1].textContent,qty:Number(l.querySelector(".qq").value||1),value:Number(l.querySelector(".qv").value||0)});if(o&&o.checked)optionals.push({id:Number(o.dataset.o),name:l.children[1].textContent.replace(/^⭐\s*/,""),qty:Number(l.querySelector(".oq").value||1),value:Number(l.querySelector(".ov").value||0)});});
 if(!items.length&&!optionals.length)return alert("Selecione um equipamento ou opcional.");
 let old=id&&db.quotes.find(q=>q.id===id),q={id:id||Date.now(),number:old?.number||"ORC-"+String(db.quotes.length+1).padStart(5,"0"),clientName,date:old?.date||new Date().toLocaleDateString("pt-BR"),eventName:$("#qeventname").value.trim(),eventDate:$("#qevent").value,eventTime:$("#qtime").value,cerimonialista:$("#qcer").value.trim(),eventLocal:$("#qlocal").value.trim(),eventCity:$("#qcity").value.trim(),items,optionals,total:Number($("#qt").value||0),notes:$("#qo").value};
 if(id)db.quotes=db.quotes.map(x=>x.id===id?q:x);else db.quotes.unshift(q);save();closeModal();quotes();pdf(q.id)
}
function delQuote(id){if(confirm("Excluir este orçamento?")){db.quotes=db.quotes.filter(x=>x.id!==id);save();quotes()}}
function pdf(id){
 let q=db.quotes.find(x=>x.id===id);if(!q)return;let w=window.open("","_blank");if(!w)return alert("Permita pop-ups para gerar o PDF.");
 let ed=q.eventDate?new Date(q.eventDate+"T00:00:00").toLocaleDateString("pt-BR"):"Não informada";
 let group={};(q.items||[]).forEach(i=>{let p=db.products.find(x=>x.id===i.productId),cat=p?.category||"Equipamentos";(group[cat]??=[]).push(i)});
 let sections=Object.entries(group).map(([cat,items])=>`<section class="equip-group"><h3>${esc(cat)}</h3>${items.map(i=>`<div class="equip-line"><span>• ${esc(i.name).toUpperCase()}</span><strong>${i.qty}x</strong></div>`).join("")}</section>`).join("");
 let or=(q.optionals||[]).map(i=>`<div class="equip-line"><span>• ${esc(i.name).toUpperCase()}</span><strong>${i.qty}x</strong></div>`).join("");
 w.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${esc(q.number)} - Impacto Pro</title><style>@page{size:A4;margin:12mm}*{box-sizing:border-box}body{font-family:Arial,Helvetica,sans-serif;color:#101820;background:#fff;margin:0;min-height:267mm}.water{position:fixed;width:430px;height:auto;left:50%;top:53%;transform:translate(-50%,-50%);opacity:.055;z-index:-1}.tools{position:fixed;right:12px;top:12px;z-index:5}.tools button{background:#0b88c7;color:#fff;border:0;border-radius:7px;padding:9px 12px;font-weight:bold}.pdf-head{border:2px solid #111;border-radius:2px;padding:13px 15px 12px}.meta-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;font-size:12px;line-height:1.9}.meta-grid b{font-size:12px}.title{text-align:center;font-size:23px;font-weight:800;letter-spacing:1px;margin:18px 0 8px;text-transform:none}.client-row{display:grid;grid-template-columns:1fr 1fr;gap:12px;border-top:1px solid #222;padding-top:9px;font-size:12px}.content{margin-top:18px}.equip-group{margin:0 0 16px}.equip-group h3{font-size:14px;margin:0 0 7px;text-decoration:underline}.equip-line{display:flex;justify-content:space-between;gap:20px;padding:3px 5px;font-size:12px;border-bottom:1px dotted #d4d4d4}.optional-title{font-size:14px;margin:16px 0 7px;text-decoration:underline}.total{margin:24px 0 0 auto;width:280px;border-top:2px solid #111;padding-top:9px;display:flex;justify-content:space-between;font-size:16px;font-weight:800}.notes{margin-top:18px;border:1px solid #cdd4d9;padding:10px;font-size:11px;white-space:pre-wrap}.validity{text-align:center;margin-top:42px;font-weight:bold;font-size:11px}.footer{text-align:center;color:#68737d;font-size:9px;margin-top:18px}@media print{.tools{display:none}.water{position:fixed}}</style></head><body><img class="water" src="${LOGO_DATA}"><div class="tools"><button onclick="window.print()">Imprimir / Salvar PDF</button></div><div class="pdf-head"><div class="meta-grid"><div><b>EVENTO:</b> ${esc(q.eventName||"Não informado")}<br><b>DATA:</b> ${esc(ed)}<br><b>HORÁRIO:</b> ${esc(q.eventTime||"Não informado")}</div><div><b>CERIMONIALISTA:</b> ${esc(q.cerimonialista||"Não informado")}<br><b>LOCAL:</b> ${esc(q.eventLocal||"Não informado")}<br><b>CIDADE:</b> ${esc(q.eventCity||"Não informada")}</div></div><div class="title">Orçamento Impacto Sonorizações</div><div class="client-row"><div><b>CLIENTE:</b> ${esc(q.clientName||"Não informado")}</div><div><b>Nº ORÇAMENTO:</b> ${esc(q.number)} &nbsp; <b>EMISSÃO:</b> ${esc(q.date)}</div></div></div><div class="content">${sections||'<div class="equip-group"><h3>Equipamentos</h3><div class="equip-line">Nenhum equipamento</div></div>'}${or?`<div class="optional-title">Opcionais</div>${or}`:""}<div class="total"><span>VALOR DO ORÇAMENTO</span><span>${money(q.total)}</span></div>${q.notes?`<div class="notes"><b>OBSERVAÇÕES</b><br>${esc(q.notes)}</div>`:""}</div><div class="validity">Este orçamento tem validade de 15 dias a partir da data de emissão.</div><div class="footer">Impacto Pro Orçamentos • Documento gerado pelo sistema</div></body></html>`);w.document.close()
}
function editPdfText(id){let q=db.quotes.find(x=>x.id===id);if(!q)return;modal(`<h3>Editar conteúdo do PDF</h3><div class="grid"><div class="field"><label>Cliente</label><input id="epc" value="${esc(q.clientName)}"></div><div class="field"><label>Evento</label><input id="epevn" value="${esc(q.eventName||"")}"></div><div class="field"><label>Cerimonialista</label><input id="epcer" value="${esc(q.cerimonialista||"")}"></div><div class="field"><label>Data do evento</label><input id="epev" type="date" value="${q.eventDate||""}"></div><div class="field"><label>Horário</label><input id="ept" type="time" value="${q.eventTime||""}"></div><div class="field"><label>Local do evento</label><input id="epl" value="${esc(q.eventLocal||"")}"></div><div class="field"><label>Cidade</label><input id="epcity" value="${esc(q.eventCity||"")}"></div><div class="field full"><label>Observações</label><textarea id="epn">${esc(q.notes||"")}</textarea></div></div><br><button onclick="savePdfText(${id})">Salvar texto</button> <button class="ghost" onclick="closeModal()">Cancelar</button>`)}
function savePdfText(id){let q=db.quotes.find(x=>x.id===id);if(!q)return;q.clientName=$("#epc").value.trim();q.eventName=$("#epevn").value.trim();q.cerimonialista=$("#epcer").value.trim();q.eventDate=$("#epev").value;q.eventTime=$("#ept").value;q.eventLocal=$("#epl").value.trim();q.eventCity=$("#epcity").value.trim();q.notes=$("#epn").value;save();closeModal();quotes()}
function rent(){const rows=db.products.map(p=>{const st=p.status||"Disponível";return `<tr><td><b>${esc(p.name)}</b><br><span class="muted">${esc(p.category||"")}</span></td><td>${p.qty}</td><td><span class="status ${statusClass(st)}">${esc(st)}</span></td><td><select onchange="setEquipmentStatus(${p.id},this.value)" style="background:#07111a;color:#fff;border:1px solid #28485e;padding:8px;border-radius:8px"><option ${st==="Disponível"?"selected":""}>Disponível</option><option ${st==="Alugado"?"selected":""}>Alugado</option><option ${st==="Manutenção"?"selected":""}>Manutenção</option></select></td></tr>`}).join("");$("#content").innerHTML=`<div class="bar"><div><h2>Equipamentos alugados</h2><span class="muted">Todos os equipamentos cadastrados no estoque aparecem automaticamente aqui.</span></div></div><div class="tablebox"><table class="table"><tr><th>Equipamento</th><th>Quantidade</th><th>Status</th><th>Alterar status</th></tr>${rows||'<tr><td colspan="4" class="empty">Nenhum equipamento cadastrado no estoque.</td></tr>'}</table></div>`}
function setEquipmentStatus(id,status){let p=db.products.find(x=>x.id===id);if(p){p.status=status;save();rent()}}
function statusClass(s){return String(s||"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/\s+/g,"")}
function history(){$("#content").innerHTML=`<div class="cards"><div class="card"><span class="card-label">ORÇAMENTOS</span><b>${db.quotes.length}</b></div><div class="card"><span class="card-label">TOTAL EM ORÇAMENTOS</span><b>${money(db.quotes.reduce((a,q)=>a+Number(q.total||0),0))}</b></div></div><div class="panel welcome"><h3>Histórico local</h3><p class="muted">Os registros ficam armazenados neste aparelho para funcionamento offline.</p></div>`}
function modal(h){let d=document.createElement("div");d.className="modal";d.id="modal";d.innerHTML=`<div class="modalbox">${h}</div>`;document.body.appendChild(d)}function closeModal(){$("#modal")?.remove()}
function downloadSystem(){modal(`<div class="download-head"><img src="./assets/impacto-pro-app-icon-512.png" alt="Impacto Pro"><div><h3>Instalar Impacto Pro</h3><p class="muted">O aplicativo usa a identidade visual oficial e pode funcionar offline.</p></div></div><div class="download-options"><div class="download-card"><h4>Android</h4><p class="muted">Instale como aplicativo pelo Chrome.</p><button onclick="installAndroid()">Instalar aplicativo</button></div><div class="download-card"><h4>Windows</h4><p class="muted">Abra no Edge/Chrome e escolha instalar aplicativo.</p><button onclick="installAndroid()">Instalar no PC</button></div><div class="download-card"><h4>Mac</h4><p class="muted">No Safari/Chrome, adicione o aplicativo à tela inicial/Apps.</p><button onclick="installAndroid()">Instalar no Mac</button></div></div><br><button class="ghost" onclick="closeModal()">Fechar</button>`)}
async function installAndroid(){if(window.deferredPrompt){window.deferredPrompt.prompt();await window.deferredPrompt.userChoice;window.deferredPrompt=null;closeModal();return}closeModal();alert("Se a opção de instalação não aparecer automaticamente, abra o menu do navegador e escolha 'Instalar aplicativo' ou 'Adicionar à tela inicial'. O ícone Impacto Pro será usado pelo sistema.")}
window.deferredPrompt=null;window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();window.deferredPrompt=e});
page("dash");updateNetworkStatus();
